{
  "versions": [
    {
      "label": "1",
      "angle": "从旅行收纳与日常外穿切入，先讲轻便携带、外观容量与打理，再回到足弓支撑、厚底和静音防滑。",
      "blocks": [
        {
          "stage": "welcome",
          "focus": "开场与轻量互动",
          "sentences": [
            {
              "display_text": "朋友们好，欢迎来到直播间，今天咱们看一双适合夏天穿的凉拖鞋。",
              "spoken_text": "朋友们好，欢迎来到直播间，今天咱们看一双适合夏天穿的凉拖鞋。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "你平时出门旅行，会不会纠结带哪双鞋？",
              "spoken_text": "你平时出门旅行，会不会纠结带哪双鞋？",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "pain",
          "focus": "旅行携带与日常外穿的选择困扰",
          "sentences": [
            {
              "display_text": "住酒店时想换上自己的拖鞋，但行李空间就那么点，多带一双都嫌沉。",
              "spoken_text": "住酒店时想换上自己的拖鞋，但行李空间就那么点，多带一双都嫌沉。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "去海边或者下楼散步，也想有一双穿脱快、看着不随便的凉拖。",
              "spoken_text": "去海边或者下楼散步，也想有一双穿脱快、看着不随便的凉拖。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "identity",
          "focus": "商品身份与基本属性",
          "sentences": [
            {
              "display_text": "这双是 Joy Share 生活选物全新上架的足弓支撑静音防滑厚底凉拖鞋，小蛮腰女款。",
              "spoken_text": "这双是 Joy Share 生活选物全新上架的足弓支撑静音防滑厚底凉拖鞋，小蛮腰女款。",
              "kind": "product_claim",
              "fact_ids": ["NAME"]
            },
            {
              "display_text": "它是一般版型，厚底平底设计，风格走居家休闲和夏日轻便路线。",
              "spoken_text": "它是一般版型，厚底平底设计，风格走居家休闲和夏日轻便路线。",
              "kind": "product_claim",
              "fact_ids": ["NAME", "SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "轻便与旅行携带",
          "sentences": [
            {
              "display_text": "这双鞋本身轻便，出门塞进行李箱不占太多地方。",
              "spoken_text": "这双鞋本身轻便，出门塞进行李箱不占太多地方。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "旅行时换上它，在房间走动或者去海边踩踩沙子，比一直穿运动鞋放松些。",
              "spoken_text": "旅行时换上它，在房间走动或者去海边踩踩沙子，比一直穿运动鞋放松些。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "平时下楼倒垃圾、小区里散个步，直接穿它出门也方便，不用系鞋带。",
              "spoken_text": "平时下楼倒垃圾、小区里散个步，直接穿它出门也方便，不用系鞋带。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "小蛮腰厚底外观与修饰",
          "sentences": [
            {
              "display_text": "再看这个叫小蛮腰的厚底造型，视觉上能修饰脚型，配短裤或者家居服都不突兀。",
              "spoken_text": "再看这个叫小蛮腰的厚底造型，视觉上能修饰脚型，配短裤或者家居服都不突兀。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "厚底是平底设计，不是那种踩上去摇摇晃晃的高跟，走路比较稳当。",
              "spoken_text": "厚底是平底设计，不是那种踩上去摇摇晃晃的高跟，走路比较稳当。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "EVA材质、快干与防臭",
          "sentences": [
            {
              "display_text": "材质是优选 E V A 环保材质，一体成型，上脚没有拼接缝磨脚背的担心。",
              "spoken_text": "材质是优选 E V A 环保材质，一体成型，上脚没有拼接缝磨脚背的担心。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "平时穿完用水冲一冲，它快干也好清洗，还有防臭的特性。",
              "spoken_text": "平时穿完用水冲一冲，它快干也好清洗，还有防臭的特性。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "浴室里洗完澡顺手冲一下，放在通风处，下次穿就比较清爽。",
              "spoken_text": "浴室里洗完澡顺手冲一下，放在通风处，下次穿就比较清爽。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "足弓支撑与久站感受",
          "sentences": [
            {
              "display_text": "这双鞋有足弓支撑，是为女性足部曲线打造的。",
              "spoken_text": "这双鞋有足弓支撑，是为女性足部曲线打造的。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "如果你在家做饭、收拾屋子，或者站着忙一阵子，脚底有支撑会舒服一些。",
              "spoken_text": "如果你在家做饭、收拾屋子，或者站着忙一阵子，脚底有支撑会舒服一些。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "加上厚底软弹缓震，走起来脚感比较柔和，能缓解久站带来的足部压力。",
              "spoken_text": "加上厚底软弹缓震，走起来脚感比较柔和，能缓解久站带来的足部压力。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "静音与防滑特性",
          "sentences": [
            {
              "display_text": "鞋底有静音和防滑特性，在家里走动时能减少对家人的打扰。",
              "spoken_text": "鞋底有静音和防滑特性，在家里走动时能减少对家人的打扰。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "浴室走动还是要留意地面，自己多注意脚下。",
              "spoken_text": "浴室走动还是要留意地面，自己多注意脚下。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "specification",
          "focus": "颜色与尺码选择",
          "sentences": [
            {
              "display_text": "颜色有粉色、红色、绿色、蓝色、橙色、葡萄紫、烟熏紫、卡其、黑色、白色，一共十个颜色。",
              "spoken_text": "颜色有粉色、红色、绿色、蓝色、橙色、葡萄紫、烟熏紫、卡其、黑色、白色，一共十个颜色。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "喜欢清爽可以看粉色、白色和蓝色；想耐看一点，卡其和黑色也好搭配。",
              "spoken_text": "喜欢清爽可以看粉色、白色和蓝色；想耐看一点，卡其和黑色也好搭配。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "尺码有三十六码到三十七码、三十八码到三十九码、四十码到四十一码、四十二码到四十三码、四十四码到四十五码。",
              "spoken_text": "尺码有三十六码到三十七码、三十八码到三十九码、四十码到四十一码、四十二码到四十三码、四十四码到四十五码。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "这是标准码，脚背比较宽或者脚型偏肉的朋友，建议斟酌大一号。",
              "spoken_text": "这是标准码，脚背比较宽或者脚型偏肉的朋友，建议斟酌大一号。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "price",
          "focus": "价格",
          "sentences": [
            {
              "display_text": "这双原价一百七十八新台币，现在活动价一百零七新台币。",
              "spoken_text": "这双原价一百七十八新台币，现在活动价一百零七新台币。",
              "kind": "product_claim",
              "fact_ids": ["PRICE", "PROMOTION"]
