        {
          "stage": "promotion",
          "focus": "限时优惠",
          "sentences": [
            {
              "display_text": "这个价格是限时下杀，喜欢的朋友可以留意一下。",
              "spoken_text": "这个价格是限时下杀，喜欢的朋友可以留意一下。",
